'use strict';
// Maré Brava — Sistemas de gameplay, mundo, persistência, combate, áudio, IA e eventos.
function hasItem(id){return G.inventory.includes(id)}
function equipped(id){const d=EQUIPMENT_DEFS[id];return !!d&&G.equipment[d.slot]===id}
function grantEquipment(id,quiet=false){const d=EQUIPMENT_DEFS[id];if(!d)return false;if(!hasItem(id))G.inventory.push(id);if(!G.equipment[d.slot])G.equipment[d.slot]=id;if(!quiet){toast(d.name+' adquirido e equipado.','gold');sound('level');}saveGame();return true}
function equipItem(id){const d=EQUIPMENT_DEFS[id];if(!d||!hasItem(id))return false;G.equipment[d.slot]=id;toast(d.name+' equipado.','gold');saveGame();return true}
function ngPlusState(){if(!G.ngPlus||typeof G.ngPlus!=='object')G.ngPlus={unlocked:false,cycle:0,clears:0,lastClearedCycle:-1,runStartKills:0};return G.ngPlus}
function ngCycle(){return Math.max(0,Math.floor(ngPlusState().cycle||0))}
function ngActive(){return ngCycle()>0}
function ngLabel(){return ngActive()?'CONTRAMARÉ +'+ngCycle():'JORNADA ORIGINAL'}
function ngTempoFactor(){return ngActive()?Math.max(.76,1-ngCycle()*.045):1}
function ngRewardFactor(){return ngActive()?1+Math.min(4,ngCycle())*.18:1}
function applyNgPlusEnemy(e){if(!ngActive()||!e)return e;const c=Math.min(5,ngCycle()),common=!e.boss&&!e.guardian&&!e.guardianMinion;if(e.boss){e.maxHp=e.hp=Math.round(e.maxHp*(1+.12*c));e.damage*=1+.055*c;e.speed*=1+.025*c;e.xp=Math.round(e.xp*(1+.2*c));e.name+=' · Contramaré';e.ngVariant='sovereign';return e}if(e.guardian){e.maxHp=e.hp=Math.round(e.maxHp*(1+.1*c));e.damage*=1+.05*c;e.speed*=1+.025*c;e.xp=Math.round(e.xp*(1+.18*c));e.ngVariant='guardian';return e}if(e.guardianMinion){e.maxHp=e.hp=Math.round(e.maxHp*(1+.05*c));e.damage*=1+.035*c;return e}if(common){e.maxHp=e.hp=Math.round(e.maxHp*(1+.055*c));e.damage*=1+.03*c;e.speed*=1+.012*c;e.xp=Math.round(e.xp*ngRewardFactor());e.ngVariant={crab:'reversalGuard',bandit:'crossfire',slime:'doubleWake',wisp:'echoBlink',mushroom:'sporeBloom',sponge:'frenzyPack'}[e.type]||'reflux';e.ngElite=!e.mini&&rng()<Math.min(.1+c*.035,.24);if(e.ngElite){e.maxHp=e.hp=Math.round(e.maxHp*1.32);e.damage*=1.1;e.xp=Math.round(e.xp*1.65);e.name+=' Veterano';e.ngBarrier=true}}return e}
function startNewGamePlus(){if(!G.started||!G.bossDefeated)return false;const old=ngPlusState(),next=Math.min(9,ngCycle()+1),ach=JSON.parse(JSON.stringify(achievementState()));ach.potionsUsed=0;ach.legacyRun=false;const data={version:CURRENT_SAVE_VERSION,meta:{savedAt:Date.now(),build:BUILD_ID},seed:G.seed,player:{x:HOME.x+27,y:HOME.y+83,hp:maxHP(),stamina:100,xp:player.xp,level:player.level,coins:player.coins,potions:player.potions,points:player.points,skills:{...player.skills},weapon:player.weapon},seals:[],guardians:[],chests:[],waypoints:['home'],playTime:0,kills:G.kills,bossDefeated:false,deathCount:G.deathCount,tutorial:{mara:true,moved:true,hooked:true,reeled:true,bird:true,attacked:true,killed:true},quests:{},secrets:[],inventory:[...G.inventory],equipment:{...G.equipment},tideTreasures:[],achievements:ach,ngPlus:{unlocked:true,cycle:next,clears:old.clears||0,lastClearedCycle:old.lastClearedCycle??-1,runStartKills:G.kills},minibosses:[],exploration:{known:[],solved:[]}};startGame(data);toast('CONTRAMARÉ +'+next+' · A ilha lembra de você.','gold');return true}
function questState(id){return G.quests[id]||null}
function questRequirementsMet(id){const q=QUEST_DEFS[id];if(!q)return false;if(q.requiresQuest&&G.quests[q.requiresQuest]?.status!=='done')return false;if(q.requiresSeals&&G.seals.length<q.requiresSeals)return false;if(q.requiresBoss===true&&!G.bossDefeated)return false;return true}
function questsForGiver(giver){return Object.entries(QUEST_DEFS).filter(([,q])=>q.giver===giver).sort((a,b)=>(a[1].arc||0)-(b[1].arc||0))}
function availableQuestForGiver(giver){return questsForGiver(giver).find(([id])=>!G.quests[id]&&questRequirementsMet(id))||null}
function activeQuestForGiver(giver){return questsForGiver(giver).find(([id])=>G.quests[id]?.status==='active')||null}
function completedQuestCount(giver){return questsForGiver(giver).filter(([id])=>G.quests[id]?.status==='done').length}
function activeQuests(){return Object.keys(G.quests).filter(id=>G.quests[id]?.status==='active'&&QUEST_DEFS[id])}
function questObjective(id){const st=G.quests[id],q=QUEST_DEFS[id];return st&&q&&st.status==='active'?q.objectives[st.step]||null:null}
function sideQuestInfo(){let best=null,bestD=Infinity;for(const id of activeQuests()){const q=QUEST_DEFS[id],st=G.quests[id],obj=questObjective(id);if(!q||!st||!obj)continue;const target=sideQuestTargetFor(id,obj),d=target&&player?dist(player,target):Infinity;if(!best||d<bestD){best={id,q,st,obj,target};bestD=d}}return best}
function sideQuestTargetFor(id,obj=questObjective(id)){if(!obj)return null;if(obj.type==='discover'||obj.type==='hookSecret'){const d=SECRET_DEFS[obj.target];return d?{x:d.x,y:d.y,name:d.name}:null}if(obj.type==='killMiniboss'){const d=MINIBOSS_DEFS[obj.target],e=enemies.find(v=>v.miniBossId===obj.target&&!v.dead);return e?{x:e.x,y:e.y,name:e.name}:d?{x:d.x,y:d.y,name:d.name}:null}if(obj.type==='tideTreasure'){const d=TIDE_TREASURES.find(v=>v.id===obj.target);return d?{x:d.x,y:d.y,name:d.name}:null}if(obj.type==='talk'){if(obj.target==='mara')return {x:HOME.x,y:HOME.y,name:'Mara'};const s=structures.find(v=>v.kind==='npc'&&v.npcId===obj.target);return s?{x:s.x,y:s.y,name:s.name}:null}return null}
function sideQuestTarget(){const info=sideQuestInfo();return info?.target||null}
function syncQuestProgress(id){const q=QUEST_DEFS[id],st=G.quests[id];if(!q||!st||st.status!=='active')return;while(st.step<q.objectives.length){const obj=q.objectives[st.step];let done=false;if((obj.type==='discover'||obj.type==='hookSecret')&&G.secrets.includes(obj.target))done=true;else if(obj.type==='killMiniboss'&&G.minibosses.includes(obj.target))done=true;else if(obj.type==='tideTreasure'&&G.tideTreasures.includes(obj.target))done=true;if(done){st.step++;continue}break}}function startQuest(id){const q=QUEST_DEFS[id];if(!q||G.quests[id]||!questRequirementsMet(id))return false;G.quests[id]={status:'active',step:0};syncQuestProgress(id);toast('Nova missão: '+q.title,'gold');sound('quest');pulseQuestHUD();saveGame();return true}
function completeQuest(id){const q=QUEST_DEFS[id],st=G.quests[id];if(!q||!st||st.status==='done')return false;st.status='done';st.step=q.objectives.length;if(q.reward?.xp)gainXP(q.reward.xp,'quest');if(q.reward?.coins)player.coins+=q.reward.coins;if(q.reward?.points)player.points+=q.reward.points;if(q.reward?.item)grantEquipment(q.reward.item,true);toast('Missão concluída: '+q.title+(q.reward?.item?' · '+EQUIPMENT_DEFS[q.reward.item].name:''),'gold');sound('questComplete');pulseQuestHUD();saveGame();return true}
function questEvent(type,data={}){for(const id of activeQuests()){const obj=questObjective(id);if(!obj)continue;let match=false;if(obj.type==='discover'&&type==='discover'&&obj.target===data.id)match=true;if(obj.type==='hookSecret'&&type==='discover'&&obj.target===data.id&&data.viaHook)match=true;if(obj.type==='killMiniboss'&&type==='killMiniboss'&&obj.target===data.id)match=true;if(obj.type==='tideTreasure'&&type==='tideTreasure'&&obj.target===data.id)match=true;if(obj.type==='talk'&&type==='talk'&&obj.target===data.npc)match=true;if(!match)continue;const st=G.quests[id];st.step++;syncQuestProgress(id);if(st.step>=QUEST_DEFS[id].objectives.length)completeQuest(id);else{toast('Missão atualizada: '+QUEST_DEFS[id].title,'gold');if(type!=='discover')sound('quest');pulseQuestHUD();saveGame()}}}
function secretCondition(id){const d=SECRET_DEFS[id];if(!d)return false;if(d.nightOnly){const ph=dayPhaseAt().id;if(ph!=='noite'&&ph!=='madrugada')return false}if(d.weatherOnly&&!d.weatherOnly.includes(weatherNow().id))return false;if(d.requiresSeals&&G.seals.length<d.requiresSeals)return false;return true}
function discoverSecret(id,viaHook=false){const d=SECRET_DEFS[id];if(!d||G.secrets.includes(id)||!secretCondition(id))return false;G.secrets.push(id);player.coins+=d.coins||0;gainXP(d.xp||0,'exploration');if(G.secrets.length===Object.keys(SECRET_DEFS).length){player.points++;toast('A ilha não guarda mais nenhum segredo conhecido. +1 ponto de habilidade.','gold')}burst(d.x,d.y,'#eadb9d',24,120);text(d.x,d.y-45,'SEGREDO DESCOBERTO','#ffe5a7',13);toast(d.name+' descoberto.','gold');sound('discover');pulseQuestHUD();questEvent('discover',{id,viaHook});gameEvent('secret',{id});saveGame();return true}
function updateSecrets(){for(const s of structures){if(s.kind!=='secret'||G.secrets.includes(s.secretId)||s.requiresHook||!secretCondition(s.secretId))continue;if(dist(s,player)<48)discoverSecret(s.secretId,false)}}
function showQuestLog(){let html=modalHeader('DIÁRIO DE BORDO · ILHA','Histórias paralelas e observações de Nilo.');const ids=Object.keys(QUEST_DEFS),started=ids.filter(id=>G.quests[id]);if(!started.length)html+='<p>Nenhuma missão secundária iniciada. Converse com Mara, Nena, Damião e Ivo.</p>';for(const id of started){const q=QUEST_DEFS[id],st=G.quests[id],reward=[];if(q.reward?.xp)reward.push(q.reward.xp+' XP');if(q.reward?.coins)reward.push(q.reward.coins+' ouro');if(q.reward?.potions)reward.push(q.reward.potions+' poção'+(q.reward.potions>1?'ões':''));if(q.reward?.points)reward.push('+'+q.reward.points+' ponto de habilidade');if(q.reward?.item)reward.push(EQUIPMENT_DEFS[q.reward.item]?.name||q.reward.item);html+=`<div class="skill-card ${st.status==='done'?'maxed':''}" style="min-height:auto"><div class="eyebrow">${st.status==='done'?'CONCLUÍDA':'ATIVA'}</div><h3>${q.title}</h3><p>${q.summary}</p><div class="quest-timeline">${q.objectives.map((obj,i)=>{const done=st.status==='done'||i<st.step,current=st.status==='active'&&i===st.step;return `<div class="quest-step ${done?'done':current?'current':''}"><i>${done?'✓':i+1}</i><span>${obj.text}</span></div>`}).join('')}</div><div class="quest-reward"><b>RECOMPENSA</b><br>${reward.join(' · ')||'—'}</div></div>`}html+='<div class="footer-note">O objetivo atual também aparece no painel da aventura e no minimapa. Missões secundárias não substituem a busca pelos três selos.</div>';html+=v3JournalHTML();setModal('quests',html);v3BindJournal()}
function showEquipment(){let html=modalHeader('EQUIPAMENTOS','Poucos itens. Regras diferentes.',`<p style="margin:2px 0 0">Cada peça altera uma mecânica real do jogo.</p>`);const slots=[['tool','FERRAMENTA'],['boots','BOTAS'],['coat','CASACO'],['ring','ANEL']];html+='<div class="skill-grid">';for(const [slot,label] of slots){html+=`<div class="skill-branch"><h4>${label}</h4>`;const owned=Object.entries(EQUIPMENT_DEFS).filter(([id,d])=>d.slot===slot&&hasItem(id));if(!owned.length)html+='<div class="skill-card" style="min-height:135px;opacity:.55"><h3>Vazio</h3><p>Explore a ilha e ajude seus habitantes.</p></div>';for(const [id,d] of owned){const on=G.equipment[slot]===id;html+=`<button class="skill-card ${on?'maxed':''}" data-equip="${id}" style="min-height:145px">${icon(d.icon)}<h3>${d.name}</h3><p>${d.desc}</p><div class="skill-rank"><span>${on?'EQUIPADO':'EQUIPAR'}</span></div></button>`}html+='</div>'}html+='</div><div class="footer-note">Equipamentos são persistidos no save. Eles não substituem a árvore de habilidades: mudam regras, não apenas números.</div>';setModal('equipment',html);for(const b of $('modal').querySelectorAll('[data-equip]'))b.onclick=()=>{equipItem(b.dataset.equip);showEquipment()}}
function achievementState(){if(!G.achievements||typeof G.achievements!=='object')G.achievements={unlocked:[],counters:{},zones:[],potionsUsed:0,legacyRun:false};if(G.achievements.legacyRun===undefined)G.achievements.legacyRun=false;return G.achievements}
function unlockAchievement(id){const a=achievementState(),d=ACHIEVEMENT_DEFS[id];if(!d||a.unlocked.includes(id))return false;a.unlocked.push(id);toast('Conquista: '+d.name,'gold');sound('level');saveGame();return true}
function gameEvent(type,data={}){const a=achievementState(),c=a.counters;if(type==='zoneEnter'){if(data.id&&!a.zones.includes(data.id))a.zones.push(data.id)}else if(type==='potionUsed')a.potionsUsed++;else if(type==='birdMultiKill')c.birdMultiKill=Math.max(c.birdMultiKill||0,data.count||0);else c[type]=(c[type]||0)+(data.count||1);if((c.hookEnemy||0)>=50)unlockAchievement('hook50');if((c.birdMultiKill||0)>=3)unlockAchievement('birdTriple');if(a.zones.length>=5)unlockAchievement('tourist');if((c.perfectDodge||0)>=10)unlockAchievement('perfect10');if((c.tideTreasure||0)>=1)unlockAchievement('tideCache');if((c.birdScoutSecret||0)>=1)unlockAchievement('birdScout');if(type==='bossDefeated'&&!a.legacyRun&&a.potionsUsed===0)unlockAchievement('noPotionBoss')}
function achievementProgress(id){const a=achievementState(),c=a.counters;if(id==='hook50')return `${Math.min(50,c.hookEnemy||0)}/50`;if(id==='birdTriple')return `${Math.min(3,c.birdMultiKill||0)}/3`;if(id==='tourist')return `${Math.min(5,a.zones.length)}/5`;if(id==='perfect10')return `${Math.min(10,c.perfectDodge||0)}/10`;if(id==='tideCache')return `${Math.min(1,c.tideTreasure||0)}/1`;if(id==='birdScout')return `${Math.min(1,c.birdScoutSecret||0)}/1`;if(id==='noPotionBoss')return a.legacyRun?'NOVA AVENTURA':a.potionsUsed===0?'SEM POÇÃO':'TENTATIVA QUEBRADA';const live=typeof livingAchievementProgress==='function'?livingAchievementProgress(id):null;if(live!==null)return live;return ''}
function showAchievements(){let html=modalHeader('CONQUISTAS','Pequenas péssimas ideias recompensadas.');const a=achievementState();html+='<div class="skill-grid">';for(const [id,d] of Object.entries(ACHIEVEMENT_DEFS)){const on=a.unlocked.includes(id);html+=`<div class="skill-card ${on?'maxed':''}" style="min-height:150px">${icon(d.icon)}<div class="eyebrow">${on?'CONCLUÍDA':'EM PROGRESSO'}</div><h3>${d.name}</h3><p>${d.desc}</p><div class="skill-rank"><span>${on?'DESBLOQUEADA':achievementProgress(id)}</span></div></div>`}html+='</div><div class="footer-note">As conquistas são locais, offline e persistidas no save. Elas observam eventos do jogo sem alterar o balanceamento.</div>';setModal('achievements',html)}
function tideLevel(time=G.playTime){return .5-.5*Math.cos(((time%TIDE_CYCLE_SECONDS)/TIDE_CYCLE_SECONDS)*TAU)}
function tideInfo(){const phase=((G.playTime%TIDE_CYCLE_SECONDS)/TIDE_CYCLE_SECONDS)*TAU,l=tideLevel(),rising=Math.sin(phase)>0;if(l<.23)return {id:'low',label:'MARÉ BAIXA',icon:'⇣',level:l};if(l>.78)return {id:'high',label:'MARÉ ALTA',icon:'⇡',level:l};return rising?{id:'rising',label:'MARÉ SUBINDO',icon:'↗',level:l}:{id:'falling',label:'MARÉ DESCENDO',icon:'↘',level:l}}
function lowTideOpen(){return tideLevel()<.36}
function tidalGroundAt(x,y,margin=0){if(!lowTideOpen())return false;for(const q of TIDE_SHOALS)if(Math.hypot(x-q.x,y-q.y)<Math.max(4,q.r-margin))return true;return false}
function terrainGroundAt(x,y,margin=0){return landAt(x,y,margin)||tidalGroundAt(x,y,margin)}
function rescueFromTide(){if(landAt(player.x,player.y,25))return;hook=null;player.dashTime=0;v3ReleaseBird(false);for(let r=35;r<=520;r+=35)for(let i=0;i<20;i++){const a=i/20*TAU,x=player.x+Math.cos(a)*r,y=player.y+Math.sin(a)*r;if(landAt(x,y,30)&&walkable(x,y,player.r)){player.x=x;player.y=y;cam.x=x;cam.y=y;toast('A maré fechou o banco de areia e empurrou Nilo de volta.','danger');return}}player.x=HOME.x+27;player.y=HOME.y+83}
function updateTideSystem(dt,quiet=false){const info=tideInfo(),cycle=Math.floor(G.playTime/TIDE_CYCLE_SECONDS);if(G.tideStage!==info.id){const prev=G.tideStage;G.tideStage=info.id;POLISH.tidePulse=1;if(!quiet&&G.playTime>5){sound('tide',info.id==='high'?1.15:.9);if(info.id==='low')toast('A maré baixou. Novos caminhos apareceram.','gold');else if(info.id==='rising')toast('A maré está subindo. Não fique preso nos bancos de areia.','danger');else if(info.id==='high')toast('Maré alta. O Recife ficou mais agressivo.','danger')}}for(const s of structures)if(s.kind==='tideCache')s.hidden=G.tideTreasures.includes(s.tideId)||!lowTideOpen();if(lowTideOpen()&&G.tideSpawnCycle!==cycle){G.tideSpawnCycle=cycle;for(let i=0;i<3;i++){const q=TIDE_SHOALS[Math.min(TIDE_SHOALS.length-1,i+1)],type=i===2?'sponge':'crab';spawnEnemy(type,q.x+(i-1)*24,q.y+18,4,{noRespawn:true,tideSpawn:true,aggro:false})}}if(!lowTideOpen()){for(const e of enemies)if(e.tideSpawn&&!e.dead)e.dead=true;if(!landAt(player.x,player.y,25))rescueFromTide()}}
function drawTideWorld(){const c=ctx,open=1-clamp((tideLevel()-.18)/.25,0,1);if(open<=.02)return;c.save();for(const q of TIDE_SHOALS){c.globalAlpha=.18+.26*open;c.beginPath();c.ellipse(q.x,q.y+7,q.r*1.08,q.r*.49,0,0,TAU);c.strokeStyle='#eef2d0';c.lineWidth=2;c.stroke();c.globalAlpha=.42+.45*open;ellipse(c,q.x,q.y,q.r,q.r*.44,'#c9c291');ellipse(c,q.x,q.y-4,q.r*.82,q.r*.32,'#ddd3a0');c.globalAlpha=.22+.4*open;for(let i=0;i<7;i++){let a=i/7*TAU+G.time*.18,rr=q.r*(.68+.08*Math.sin(G.time*1.4+i));circle(c,q.x+Math.cos(a)*rr,q.y+Math.sin(a)*rr*.42,1.4+(i%2),i%3===0?'#eef2d4':'#b8c4a1')}c.globalAlpha=.28*open;for(let i=0;i<4;i++){let a=i/4*TAU+.7,rr=q.r*.42;ellipse(c,q.x+Math.cos(a)*rr,q.y+Math.sin(a)*rr*.35,7,2.2,'#74896b',a*.2)}}c.restore()}
function openTideCache(s){if(!s||s.hidden||G.tideTreasures.includes(s.tideId))return false;G.tideTreasures.push(s.tideId);player.coins+=55;gainXP(65,'exploration');burst(s.x,s.y,'#f0dc99',36,150);text(s.x,s.y-42,'TESOURO DA MARÉ','#ffe6a4',14);toast('A maré devolveu um tesouro antigo.','gold');questEvent('tideTreasure',{id:s.tideId});gameEvent('tideTreasure');s.hidden=true;saveGame();return true}
function nearestBirdClue(){let best=null,bd=260;for(const s of structures){if(s.kind==='secret'&&!G.secrets.includes(s.secretId)&&secretCondition(s.secretId)){const d=dist(player,s);if(d<bd){best=s;bd=d}}else if((s.kind==='tideCache'||s.kind==='eventBirdStash')&&!s.hidden){const d=dist(player,s);if(d<bd){best=s;bd=d}}else if(typeof livingBirdTarget==='function'&&livingBirdTarget(s)){const d=dist(player,s);if(d<bd){best=s;bd=d}}}return best}
function birdScout(){const target=nearestBirdClue();if(!target){toast('Pipoca investigou a área e concluiu que o problema é você.');return false}bird.scoutTarget=target;bird.scoutTime=2.4;bird.manualCD=Math.max(bird.manualCD,1.1);text(bird.x,bird.y-35,'?','#f7e4ab',16);return true}
function finishBirdScout(){const t=bird.scoutTarget;if(!t)return;if(t.kind==='secret'){if(t.secretId==='pipocaNest'){discoverSecret(t.secretId,false);toast('Pipoca encontrou algo que, estranhamente, parece pertencer a ele.','gold')}else{bird.hintTarget=t;bird.hintTime=7;text(t.x,t.y-38,'PIPOCA DESCONFIA','#f4dfa0',10);toast('Pipoca está insistindo que há algo estranho por perto.')}gameEvent('birdScoutSecret')}else if(t.kind==='tideCache'){bird.hintTarget=t;bird.hintTime=6;text(t.x,t.y-40,'ALGO BRILHA','#f4dfa0',10)}else if(typeof finishLivingBirdScout==='function'&&finishLivingBirdScout(t)){}else if(t.kind==='eventBirdStash'){text(t.x,t.y-40,'PIPOCA ACHOU','#f4dfa0',10);burst(t.x,t.y,'#eee2b2',18,85);player.coins=Math.min(999999,player.coins+9);gainXP(12,'exploration');toast('Pipoca encontrou um botão velho, duas moedas suspeitas e 9 ouro. O botão é dele.','gold');finishDynamicEvent('complete')}burst(t.x,t.y,'#eee2b2',12,65);bird.scoutTarget=null;bird.scoutTime=0}
function updateBird(dt){if(v3BirdUpdate(dt))return;bird.autoTimer-=dt;bird.manualCD=Math.max(0,bird.manualCD-dt);bird.attackAnim=Math.max(0,bird.attackAnim-dt);bird.rescueCD=Math.max(0,(bird.rescueCD||0)-dt);bird.opportunity=Math.max(0,(bird.opportunity||0)-dt);bird.celebrate=Math.max(0,(bird.celebrate||0)-dt);bird.hintTime=Math.max(0,(bird.hintTime||0)-dt);bird.wing+=dt*(bird.scoutTarget?18:weatherNow().id==='storm'?17:12);if(bird.scoutTarget){bird.scoutTime-=dt;bird.x=lerp(bird.x,bird.scoutTarget.x,Math.min(1,dt*5.8));bird.y=lerp(bird.y,bird.scoutTarget.y-34,Math.min(1,dt*5.8));if(dist(bird,{x:bird.scoutTarget.x,y:bird.scoutTarget.y-34})<24||bird.scoutTime<=0)finishBirdScout();return}if(player.hp/maxHP()<.35&&bird.rescueCD<=0){const e=nearestEnemy(player,290);if(e){bird.rescueCD=18;birdAttack(false,true);toast('Pipoca decidiu que você está dando trabalho demais.','gold')}}if(bird.autoTimer<=0){if(!birdAttack(false))bird.autoTimer=.7}let tx=player.x+Math.cos(G.time*.9)*32+10,ty=player.y-41+Math.sin(G.time*1.3)*8;if(player.combat>0){const e=nearestEnemy(player,330);if(e){const a=angle(player,e);tx=player.x+Math.cos(a)*38;ty=player.y-46+Math.sin(a)*15}}if(weatherNow().id==='storm'){tx=lerp(tx,player.x+18,.55);ty=lerp(ty,player.y-35,.55)}bird.x=lerp(bird.x,tx,Math.min(1,dt*5));bird.y=lerp(bird.y,ty,Math.min(1,dt*5))}
function rng(){seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296}function rand(a,b){return a+rng()*(b-a)}function pick(arr){return arr[Math.floor(rng()*arr.length)]}function noise(x,y){return Math.abs(Math.sin(x*12.9898+y*78.233)*43758.5453)%1}
function edgeRadius(a){return 1+.056*Math.sin(a*3+1)+.032*Math.sin(a*7)+.024*Math.cos(a*11)}
function landAt(x,y,margin=0){const nx=(x-WORLD.cx)/WORLD.rx,ny=(y-WORLD.cy)/WORLD.ry;return Math.hypot(nx,ny)<edgeRadius(Math.atan2(ny,nx))-margin/WORLD.ry}
function zoneAt(x,y){if(x>3670&&y>2460)return {id:'reef',name:'Recife Esquecido',sub:'CORAÇÃO DA MARÉ - NV. 5-7',color:'#75a79b'};if(x>3510)return {id:'dunes',name:'Dunas Douradas',sub:'AREIA, SOL E PERIGO - NV. 3-5',color:'#c0b184'};if(y<1640)return {id:'forest',name:'Bosque Sussurrante',sub:'SOB A COPA DAS ÁRVORES - NV. 2-3',color:'#648c6b'};if(y>3030)return {id:'marsh',name:'Brejo Brilhante',sub:'CUIDADO ONDE PISA - NV. 3-4',color:'#527f72'};return {id:'meadow',name:'Campos do Vento',sub:'TERRITÓRIO LIVRE - NV. 1-2',color:'#85a57b'}}
function worldHour(){return (WORLD_START_HOUR+(G.playTime/GAME_DAY_SECONDS)*24)%24}
function dayPhaseAt(h=worldHour()){if(h<5)return {id:'madrugada',label:'MADRUGADA',icon:'☾'};if(h<8)return {id:'manha',label:'MANHÃ',icon:'◐'};if(h<17)return {id:'dia',label:'DIA',icon:'☀'};if(h<19.5)return {id:'entardecer',label:'ENTARDECER',icon:'◒'};if(h<23)return {id:'noite',label:'NOITE',icon:'☾'};return {id:'madrugada',label:'MADRUGADA',icon:'☾'}}
function formatWorldTime(){const h=worldHour(),hh=Math.floor(h),mm=Math.floor((h-hh)*60);return String(hh).padStart(2,'0')+':'+String(mm).padStart(2,'0')}
function nightStrength(){const h=worldHour();if(h>=20||h<5)return .58;if(h>=18&&h<20)return .58*((h-18)/2);if(h>=5&&h<7)return .58*(1-(h-5)/2);return 0}
function duskStrength(){const h=worldHour();if(h>=17&&h<20)return Math.sin((h-17)/3*Math.PI);if(h>=5&&h<7.5)return Math.sin((7.5-h)/2.5*Math.PI);return 0}
function updateTimeSystem(){const ph=dayPhaseAt();if(!G.lastDayPhase){G.lastDayPhase=ph.id;return}if(ph.id!==G.lastDayPhase){G.lastDayPhase=ph.id;if(G.playTime>8){const msg={manha:'A luz volta à Ilha das Marés.',dia:'O dia se firma sobre a ilha.',entardecer:'O sol começa a afundar no horizonte.',noite:'A noite caiu. Algumas criaturas ficam mais ousadas.',madrugada:'A madrugada tomou a ilha.'}[ph.id];if(msg)toast(msg,ph.id==='noite'||ph.id==='madrugada'?'danger':'')}}}
function drawBiomeAtmosphere(){if(!G.started||!player)return;const c=ctx,z=zoneAt(player.x,player.y).id,t=G.time,q=effectsFactor(),count=Math.max(mobileRenderEnabled?.()?renderProfile().biomeMin:5,Math.round(18*q));c.save();if(z==='meadow'){c.globalAlpha=.2;for(let i=0;i<count;i++){let x=cam.x-500+((i*173+t*8)%1000),y=cam.y-360+((i*89+Math.sin(t+i)*24+720)%720);circle(c,x,y,1.2,'#e8ddb0')}}else if(z==='forest'){c.globalAlpha=.24;for(let i=0;i<count;i++){let x=cam.x-520+((i*211+t*15)%1040),y=cam.y-380+((i*101+t*5)%760);c.save();c.translate(x,y);c.rotate(t*.35+i);ellipse(c,0,0,3.6,1.7,i%2?'#9eb07a':'#c1bd7f');c.restore()}}else if(z==='marsh'){const n=nightStrength();c.globalAlpha=.14+.34*n;for(let i=0;i<count;i++){let x=cam.x-470+((i*197+Math.sin(t*.35+i)*80+940)%940),y=cam.y-330+((i*131+Math.cos(t*.28+i)*55+660)%660);circle(c,x,y,1.5+n*1.3,i%2?'#d7db91':'#90c9ab')}}else if(z==='dunes'){c.globalAlpha=weatherNow().id==='wind'?.24:.12;for(let i=0;i<count;i++){let x=cam.x-540+((i*157+t*(weatherNow().id==='wind'?70:24))%1080),y=cam.y-320+((i*109+t*5)%640);line(c,[[x,y],[x+12,y-2]],'#e0cf9a',1)}}else if(z==='reef'){c.globalAlpha=.22;for(let i=0;i<count;i++){let x=cam.x-500+((i*181+t*12)%1000),y=cam.y-350+((i*127+Math.sin(t*.8+i)*20+700)%700);circle(c,x,y,1.2+(i%3)*.45,i%2?'#d6e7ca':'#f0d7bf')}}c.restore()}
function drawDayNightOverlay(){const c=ctx,n=nightStrength(),d=duskStrength();if(d>0){c.save();c.globalAlpha=.10*d;c.fillStyle='#c77445';c.fillRect(0,0,width,height);c.restore()}if(n>0){c.save();c.globalAlpha=n;c.fillStyle='#071a2c';c.fillRect(0,0,width,height);const px=(player.x-cam.x)*zoom+width/2,py=(player.y-cam.y)*zoom+height/2,gr=c.createRadialGradient(px,py,25,px,py,190);gr.addColorStop(0,'rgba(255,227,164,.16)');gr.addColorStop(.45,'rgba(255,227,164,.05)');gr.addColorStop(1,'rgba(255,227,164,0)');c.globalCompositeOperation='screen';c.fillStyle=gr;c.fillRect(0,0,width,height);c.restore()}}
const WEATHER={clear:{id:'clear',label:'CÉU LIMPO',icon:'·'},wind:{id:'wind',label:'VENTO FORTE',icon:'≋'},rain:{id:'rain',label:'CHUVA',icon:'☂'},fog:{id:'fog',label:'NEBLINA',icon:'≈'},storm:{id:'storm',label:'TEMPESTADE',icon:'ϟ'}};
function worldRand(n,salt=0){const v=Math.sin((n+1)*12.9898+(G.seed+salt)*.017)*43758.5453123;return v-Math.floor(v)}
function weatherAt(time=G.playTime){if(G.weatherOverride&&WEATHER[G.weatherOverride])return WEATHER[G.weatherOverride];const slot=Math.floor(time/WEATHER_SLOT_SECONDS),r=worldRand(slot,91),h=(WORLD_START_HOUR+(time/GAME_DAY_SECONDS)*24)%24;let id=r<.43?'clear':r<.59?'wind':r<.76?'rain':r<.9?'fog':'storm';if((h>=23||h<6)&&id==='clear'&&worldRand(slot,117)>.48)id='fog';return WEATHER[id]}
function weatherNow(){return WEATHER[G.weather]||weatherAt()}
function weatherEnemySpeed(e){const w=weatherNow().id;let m=1;if(e.type==='slime'&&(w==='rain'||w==='storm'))m*=1.2;if(e.type==='wisp'&&w==='fog')m*=1.08;if(tideInfo().id==='high'&&zoneAt(e.x,e.y).id==='reef'&&['crab','sponge'].includes(e.type))m*=1.12;return m}
function updateWeatherSystem(dt,quiet=false){const spec=weatherAt(),slot=Math.floor(G.playTime/WEATHER_SLOT_SECONDS);G.weatherFlash=Math.max(0,G.weatherFlash-dt*2.8);if(G.weather!==spec.id||G.weatherSlot!==slot){const changed=G.weather!==spec.id;G.weather=spec.id;G.weatherSlot=slot;G.lightningTimer=2.8+worldRand(slot,303)*4;if(changed){POLISH.weatherFade=0;if(!quiet&&G.playTime>8)sound('weather',spec.id==='storm'?1.25:spec.id==='rain'?.95:.8)}if(changed&&!quiet&&G.playTime>8){const msg={clear:'As nuvens se abriram sobre a ilha.',wind:'O vento ganhou força.',rain:'Começou a chover na Ilha das Marés.',fog:'Uma neblina espessa tomou os caminhos.',storm:'Uma tempestade está chegando.'}[spec.id];toast(msg,spec.id==='storm'?'danger':'')}}if(spec.id==='storm'&&G.started&&!G.overlay){G.lightningTimer-=dt;const boss=enemies.some(e=>!e.dead&&(e.boss&&e.awake||e.guardian)&&dist(e,player)<520);if(G.lightningTimer<=0&&!boss&&dist(player,HOME)>210){let a=worldRand(Math.floor(G.time*10),511)*TAU,d=75+worldRand(Math.floor(G.time*10),512)*155,x=player.x+Math.cos(a)*d,y=player.y+Math.sin(a)*d;if(landAt(x,y,30))addHazard('lightning',x,y,38,.78,12,null,{life:1.35});G.lightningTimer=4+worldRand(slot+Math.floor(G.time),513)*4.5}}}
function drawWeatherOverlay(){const c=ctx,w=weatherNow().id,t=G.time,fade=POLISH.weatherFade;if(w==='rain'||w==='storm'){c.save();c.globalAlpha=(w==='storm'?.48:.34)*fade;c.strokeStyle=w==='storm'?'#d6e5dd':'#c9ded7';c.lineWidth=1;const count=Math.round((w==='storm'?120:82)*effectsFactor());for(let i=0;i<count;i++){let x=(i*83+t*(w==='storm'?390:270)+Math.sin(i*2.3)*90)%(width+160)-80,y=(i*137+t*(w==='storm'?610:430))%(height+120)-60;c.beginPath();c.moveTo(x,y);c.lineTo(x-10,y+18);c.stroke()}c.restore()}if(w==='fog'){c.save();c.globalAlpha=.16*fade;c.fillStyle='#d3dfd1';for(let i=0;i<Math.max(mobileRenderEnabled?.()?2:3,Math.round(6*effectsFactor()));i++){let x=((i*287+t*15)%(width+420))-210,y=height*(.18+i*.13)+Math.sin(t*.22+i)*35;c.beginPath();c.ellipse(x,y,230,75,0,0,TAU);c.fill()}c.fillStyle='rgba(208,220,211,.09)';c.fillRect(0,0,width,height);c.restore()}if(w==='wind'){c.save();c.strokeStyle='#d6dfc8';c.globalAlpha=.18*fade;for(let i=0;i<Math.max(mobileRenderEnabled?.()?renderProfile().windMin:14,Math.round(36*effectsFactor()));i++){let x=(i*173+t*170)%(width+220)-110,y=(i*71+Math.sin(i*4.1)*120+height*3)%height;c.beginPath();c.moveTo(x,y);c.quadraticCurveTo(x+35,y-6,x+70,y);c.stroke()}c.restore()}if(w==='storm'){c.save();c.globalAlpha=fade;c.fillStyle='rgba(7,18,25,.08)';c.fillRect(0,0,width,height);c.restore()}if(G.weatherFlash>0){c.save();c.globalAlpha=clamp(G.weatherFlash*2.8,0,.65);c.fillStyle='#eef7ee';c.fillRect(0,0,width,height);c.restore()}}

function maxHP(){return 120+(player.level-1)*18+player.skills.vigor*25}function attackDamage(){return 20+(player.level-1)*3.8+player.weapon*6}function xpNextFor(level){level=Math.max(1,Math.floor(Number(level)||1));return 3*Math.round(BALANCE.progression.levelBase+level*BALANCE.progression.levelLinear+level*level*BALANCE.progression.levelCurve)}function xpNext(){return xpNextFor(player.level)}function hookRange(){return 365+player.skills.line*70+(equipped('navigator_hook')?90:0)}function hookCooldown(){return Math.max(.58,1.12-player.skills.line*.13)}function birdCooldown(){return Math.max(5,9-player.skills.bird*.85)}function dashCooldown(){return Math.max(.65,1.3-player.skills.agility*.17)}
function combatMeleeSource(source){return ['sword','combo3','charged','hook','pull','crate'].includes(source)}
function combatRecordDamage(source,amount){if(source==='poop')PLAYTEST.birdDamage+=amount;else if(source==='charged')PLAYTEST.chargedDamage+=amount;else if(source==='hook'||source==='pull'||source==='crate')PLAYTEST.hookDamage+=amount;else if(source==='sword'||source==='combo3')PLAYTEST.meleeDamage+=amount}
function armCounter(kind='timing',duration=.85){player.counterWindow=Math.max(player.counterWindow||0,duration);player.counterSource=kind}
function registerBirdControl(e,boosted=false){if(!e||e.dead)return 1;if(boosted){e.birdDiminish=0;e.birdDiminishTimer=BALANCE.combat.birdDiminishWindow;return 1}const chained=(e.birdDiminishTimer||0)>0;e.birdDiminish=chained?Math.min(3,(e.birdDiminish||0)+1):0;e.birdDiminishTimer=BALANCE.combat.birdDiminishWindow;const scale=[1,.72,.5,BALANCE.combat.birdStunFloor][e.birdDiminish]||BALANCE.combat.birdStunFloor;if(e.birdDiminish>0)PLAYTEST.birdDiminishedHits++;if(e.birdDiminish===2&&!e.birdAdaptHint){e.birdAdaptHint=true;text(e.x,e.y-e.r-43,'RESISTINDO AO ATORDOAMENTO','#d9d7ae',9)}return scale}

function makePlayer(){return {x:HOME.x+27,y:HOME.y+83,r:13,hp:120,stamina:100,xp:0,level:1,coins:0,potions:0,points:1,skills:{line:0,harpoon:0,bird:0,rain:0,vigor:0,agility:0},weapon:0,angle:-.25,moving:false,walk:0,attackCD:0,attackAnim:0,attackAnimMax:.24,attackAngle:0,attackStep:1,comboStep:0,comboTimer:0,charging:false,chargeTime:0,chargePulse:0,chargeStage:0,attackBuffer:0,attackPressBuffered:false,undertowCharge:0,dashCD:0,dashTime:0,dashX:0,dashY:0,invuln:0,perfectWindow:0,perfectReady:false,perfectFlash:0,perfectCount:0,parryCD:0,parryWindow:0,parryFlash:0,parryCount:0,counterWindow:0,counterSource:'',slowTime:0,coatCD:0,hookCD:0,potionCD:0,flash:0,combat:0}}
function resize(){width=innerWidth;height=innerHeight;if(!GAME_RENDER.ready||!ctx)return false;dpr=typeof effectiveRenderPixelRatio==='function'?effectiveRenderPixelRatio():Math.min(devicePixelRatio||1,dprCap());canvas.width=Math.max(1,Math.round(width*dpr));canvas.height=Math.max(1,Math.round(height*dpr));canvas.style.width=width+'px';canvas.style.height=height+'px';zoom=width<650?.86:1;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.imageSmoothingEnabled=true;if(typeof configureMinimapBacking==='function')configureMinimapBacking();BOOT.canvas.width=canvas.width;BOOT.canvas.height=canvas.height;BOOT.canvas.cssWidth=width;BOOT.canvas.cssHeight=height;BOOT.env.dprEffective=dpr;BOOT.env.renderProfile=typeof mobileRenderReport==='function'?mobileRenderReport():null;return true}
addEventListener('resize',()=>{if(GAME_RENDER.ready)resize()});
function circle(c,x,y,r,fill,stroke,line=1){PERF.drawCalls++;c.beginPath();c.arc(x,y,Math.max(.01,r),0,TAU);if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.lineWidth=line;c.stroke()}}
function ellipse(c,x,y,rx,ry,fill,rotation=0){PERF.drawCalls++;rx=Math.max(.01,rx);ry=Math.max(.01,ry);c.beginPath();if(typeof c.ellipse==='function')c.ellipse(x,y,rx,ry,rotation,0,TAU);else{c.save();c.translate(x,y);c.rotate(rotation);c.scale(rx,ry);c.arc(0,0,1,0,TAU);c.restore()}c.fillStyle=fill;c.fill()}
function rr(c,x,y,w,h,r,fill,stroke,line=1){PERF.drawCalls++;c.beginPath();if(typeof c.roundRect==='function')c.roundRect(x,y,w,h,r);else{const rad=Math.max(0,Math.min(Number(r)||0,Math.abs(w)/2,Math.abs(h)/2));c.moveTo(x+rad,y);c.lineTo(x+w-rad,y);c.quadraticCurveTo(x+w,y,x+w,y+rad);c.lineTo(x+w,y+h-rad);c.quadraticCurveTo(x+w,y+h,x+w-rad,y+h);c.lineTo(x+rad,y+h);c.quadraticCurveTo(x,y+h,x,y+h-rad);c.lineTo(x,y+rad);c.quadraticCurveTo(x,y,x+rad,y);c.closePath()}if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.lineWidth=line;c.stroke()}}
function line(c,points,color,w=1){PERF.drawCalls++;c.beginPath();for(let i=0;i<points.length;i++)i?c.lineTo(points[i][0],points[i][1]):c.moveTo(points[i][0],points[i][1]);c.strokeStyle=color;c.lineWidth=w;c.lineCap='round';c.lineJoin='round';c.stroke()}
function islandPath(scale=1){const p=new Path2D();for(let i=0;i<=220;i++){let a=i/220*TAU,r=edgeRadius(a)*scale,x=WORLD.cx+Math.cos(a)*WORLD.rx*r,y=WORLD.cy+Math.sin(a)*WORLD.ry*r;i?p.lineTo(x,y):p.moveTo(x,y)}p.closePath();return p}
const ROADS=[[HOME,{x:1650,y:2450},{x:2100,y:2150},{x:2450,y:1100}],[{x:2100,y:2150},{x:3000,y:2070},{x:3700,y:2200},{x:4260,y:1800}],[{x:2100,y:2150},{x:2340,y:2830},{x:2470,y:3240},{x:2700,y:3470}],[{x:3700,y:2200},{x:3710,y:2710},{x:3990,y:3020},BOSS_POS]];
function segmentDistance(p,a,b){let dx=b.x-a.x,dy=b.y-a.y,t=clamp(((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy),0,1);return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy)}
function onRoad(x,y,pad=55){const p={x,y};return ROADS.some(road=>road.some((q,i)=>i&&segmentDistance(p,road[i-1],q)<pad))}
function protectedPlace(x,y){return dist({x,y},HOME)<215||dist({x,y},BOSS_POS)<325||GUARDIANS.some(q=>dist({x,y},q)<170)||Object.values(MINIBOSS_DEFS).some(q=>dist({x,y},q)<125)||structures.some(q=>dist({x,y},q)<110)||onRoad(x,y,55)}
