 for(let i=0;i<3800;i++){let x=rand(0,WORLD.w),y=rand(0,WORLD.h),l=rand(8,45);line(c,[[x,y],[x+l,y+1]],pick(['#44847a55','#77ad9340','#1d54554d']),rand(1,3))}
 landPath=islandPath();innerPath=islandPath(.953);c.strokeStyle='#244f501f';c.lineWidth=170;c.stroke(landPath);c.strokeStyle='#68a39788';c.lineWidth=93;c.stroke(landPath);c.strokeStyle='#a9c5a477';c.lineWidth=44;c.stroke(landPath);c.fillStyle='#ceca96';c.fill(landPath);c.strokeStyle='#e2ddae';c.lineWidth=9;c.stroke(landPath);c.fillStyle='#85a47c';c.fill(innerPath);
 c.save();c.clip(innerPath);
 c.beginPath();c.moveTo(0,0);c.lineTo(WORLD.w,0);c.lineTo(WORLD.w,1450);c.bezierCurveTo(4210,1330,3440,1760,2850,1570);c.bezierCurveTo(2360,1510,1950,1880,1410,1600);c.bezierCurveTo(1030,1510,720,1680,0,1470);c.closePath();c.fillStyle='#668b6d';c.fill();
