function impactProfile(e,source){if(source==='poop')return {colors:['#f1ecd6','#d8dfbd','#fff7e5'],count:9,speed:92};const map={slime:['#9fd08c','#c9e6aa','#6fa879'],crab:['#d69670','#e9bc83','#9b7256'],bandit:['#d6b07b','#ead5a3','#8d785f'],mushroom:['#c29bad','#e0c1c6','#917985'],wisp:['#c9e7c5','#eff3cc','#91c9b2'],sponge:['#e4c76f','#f5df9e','#b99d51'],boss:['#edc96d','#fff0a8','#c49348']};return {colors:map[e.boss?'boss':e.type]||['#edc690','#fff0c6','#cba773'],count:e.boss?12:e.guardian?10:7,speed:e.boss?145:110}}
