function combatImpact(e,source,critical=false,strong=false){e.impact=Math.max(e.impact||0,critical?1:strong?.9:.62);e.impactAngle=angle(player,e);const shake=critical?6:strong?4.5:2.2;if(!reducedMotion())G.shake=Math.max(G.shake,shake);if(strong||critical)G.hitStop=Math.max(G.hitStop,critical?.09:.065);POLISH.hitMarker=1;POLISH.hitStrong=!!strong;POLISH.hitCritical=!!critical;cameraImpact(e.impactAngle,critical?1.15:strong?.85:.32);impactBurst(e,source,critical,strong)}
function currentAim(){if(pointer.known){let p=screenToWorld(pointer.x,pointer.y),base=Math.atan2(p.y-player.y,p.x-player.x);if(PREFS.aimAssist>0){let best=null,score=.11+PREFS.aimAssist*.09;for(const e of enemies){if(e.dead||e.boss&&!e.awake)continue;const d=dist(player,e);if(d>430)continue;const da=Math.abs(Math.atan2(Math.sin(angle(player,e)-base),Math.cos(angle(player,e)-base)));const s=da+(d/430)*.025;if(da<(.11+PREFS.aimAssist*.09)&&s<score){score=s;best=e}}if(best)return angle(player,best)}return base}let e=nearestEnemy(player,350+PREFS.aimAssist*45);return e?angle(player,e):player.angle}
