function gainXP(amount,source='other'){amount=Math.max(0,Math.round(Number(amount)||0));if(!amount)return 0;const key=v3Own(PLAYTEST.xpSources,source)?source:'other';PLAYTEST.xpSources[key]+=amount;PLAYTEST.xpGained+=amount;player.xp+=amount;while(player.xp>=xpNext()&&player.level<40){player.xp-=xpNext();player.level++;player.points++;PLAYTEST.levelUps++;const beforeHp=player.hp,heal=Math.ceil(maxHP()*BALANCE.levelUpHeal);player.hp=Math.min(maxHP(),player.hp+heal);PLAYTEST.levelUpHealing+=Math.max(0,player.hp-beforeHp);player.stamina=100;burst(player.x,player.y,'#f5d890',36,150);text(player.x,player.y-60,'NÍVEL '+player.level,'#ffe4a2',23);toast('Nível '+player.level+'! Metade da vida restaurada e +1 ponto de habilidade.','gold');sound('level');saveGame()}return amount}
function enemyXpReward(e){const raw=Math.max(0,Math.round(e?.xp||0));if(!raw)return {raw,award:0,source:'common',multiplier:0};let source='common',multiplier=BALANCE.progression.commonXp;if(e.boss){source='boss';multiplier=1}else if(e.guardian){source='guardian';multiplier=1}else if(e.miniBossId){source='elite';multiplier=BALANCE.progression.miniXp}else if(e.ngElite){source='elite';multiplier=BALANCE.progression.ngEliteXp}else if(e.eventId){source='event';multiplier=BALANCE.progression.eventMobXp}else if((e.rewardKills||0)>0){source='common';multiplier=BALANCE.progression.respawnXp}const award=Math.max(raw>0?1:0,Math.round(raw*multiplier));return {raw,award,source,multiplier}}
