function attack(){if(!G.started||G.overlay||player.hp<=0||player.attackCD>0||player.charging)return;G.tutorial.attacked=true;PLAYTEST.attacks++;player.attackBuffer=0;player.attackPressBuffered=false;const step=player.comboTimer>0?player.comboStep%3+1:1;player.comboStep=step;player.comboTimer=.62;player.attackStep=step;const cfg=[null,{cd:.31,anim:.21,range:76,arc:1.22,mult:1,knock:10},{cd:.34,anim:.23,range:82,arc:1.3,mult:1.1,knock:14},{cd:.48,anim:.29,range:92,arc:1.42,mult:1.34,knock:27}][step];player.attackCD=cfg.cd;player.attackAnim=player.attackAnimMax=cfg.anim;player.attackAngle=currentAim();player.angle=player.attackAngle;let hit=false;for(let e of enemies){if(e.dead)continue;let d=dist(player,e),da=Math.atan2(Math.sin(angle(player,e)-player.attackAngle),Math.cos(angle(player,e)-player.attackAngle));if(d<cfg.range+e.r&&(Math.abs(da)<cfg.arc||d<31)){const crit=Math.random()<.1,source=step===3?'combo3':'sword';damageEnemy(e,attackDamage()*cfg.mult*(crit?1.55:1),source,crit,step===3);if(!e.dead&&!(e.boss&&!e.awake))moveEntity(e,Math.cos(player.attackAngle)*cfg.knock/e.weight,Math.sin(player.attackAngle)*cfg.knock/e.weight,true);hit=true}}for(let p of props){if(p.dead)continue;let d=dist(player,p),da=Math.atan2(Math.sin(angle(player,p)-player.attackAngle),Math.cos(angle(player,p)-player.attackAngle));if(d<cfg.range&&(Math.abs(da)<cfg.arc+0.13||d<28)){breakProp(p);hit=true}}if(hit)PLAYTEST.hits++;PLAYTEST.maxCombo=Math.max(PLAYTEST.maxCombo,step);sound(hit?(step===3?'heavy':'hit'):'sword',step===3?1.15:1)}
function beginAttackCharge(){if(!G.started||G.overlay||player.hp<=0||player.charging)return false;if(player.attackCD>0){if(player.attackCD<=.14){player.attackPressBuffered=true;return true}return false}player.charging=true;player.chargeTime=0;player.chargePulse=0;player.chargeStage=0;player.comboTimer=0;return true}
function releaseAttackCharge(){if(player.attackPressBuffered){player.attackPressBuffered=false;player.attackBuffer=.14;return true}if(!player.charging)return false;const held=player.chargeTime;player.charging=false;player.chargeTime=0;player.chargePulse=0;player.chargeStage=0;if(held>=.42)return chargedAttack(held);attack();return true}
