function resolveGuardianAttack(e,kind){if(kind==='mossClaw'){addHazard('enemy',e.x,e.y,112,.08,e.damage+2,e);e.guard=.8;e.guardAngle=angle(e,player)}else if(kind==='mossRoots'){addHazard('root',e.strikeX,e.strikeY,82,.5,Math.max(3,e.damage*.45),e,{life:3.2,tick:.2});if(ngActive())addHazard('root',e.strikeX+Math.cos(G.time)*95,e.strikeY+Math.sin(G.time)*70,58,.68,Math.max(3,e.damage*.32),e,{life:2.8,tick:.2})}else if(kind==='mossLunge'){let dx=e.strikeX-e.x,dy=e.strikeY-e.y,d=Math.hypot(dx,dy),step=Math.min(170,d);if(d>0)moveEntity(e,dx/d*step,dy/d*step,true);addHazard('root',e.x,e.y,68,.15,Math.max(3,e.damage*.35),e,{life:2.5,tick:.2});if(dist(e,player)<e.r+player.r+34)hurtPlayer(e.damage+4,e)}else if(kind==='mireLeap'){let dx=e.strikeX-e.x,dy=e.strikeY-e.y,d=Math.hypot(dx,dy),step=Math.min(150,d);if(d>0)moveEntity(e,dx/d*step,dy/d*step,true);addHazard('sticky',e.x,e.y,78,.05,0,e,{life:4.4});if(dist(e,player)<e.r+player.r+32)hurtPlayer(e.damage+2,e)}else if(kind==='mireBurst'){for(let i=0;i<3+e.guardianPhase+(ngActive()?Math.min(2,ngCycle()):0);i++){let a=i/(3+e.guardianPhase+(ngActive()?Math.min(2,ngCycle()):0))*TAU+G.time,x=player.x+Math.cos(a)*75,y=player.y+Math.sin(a)*58;addHazard('sticky',x,y,48,.38+i*.05,0,e,{life:3.5})}}else if(kind==='bronzeClaw'){addHazard('enemy',e.x,e.y,106,.06,e.damage+3,e)}else if(kind==='bronzeCharge'){let dx=e.strikeX-e.x,dy=e.strikeY-e.y,d=Math.hypot(dx,dy),step=Math.min(235,d);if(d>0)moveEntity(e,dx/d*step,dy/d*step,true);if(dist(e,player)<e.r+player.r+42)hurtPlayer(e.damage+6,e);burst(e.x,e.y,'#e1bd75',22,150)}else if(kind==='bronzeNova'){const shots=8+e.guardianPhase*2+(ngActive()?Math.min(4,ngCycle()*2):0);for(let i=0;i<shots;i++)enemyShot(e,i/shots*TAU,175+e.guardianPhase*10+(ngActive()?12:0),'bubble')}e.parryable=false;e.hookBreakable=false}
