 if(d>720){e.leashTime=(e.leashTime||0)+dt;e.parryable=false;e.hookBreakable=false;e.guardianPending=null;e.windup=0;e.aggro=false;if(homeD>18){let a=Math.atan2(e.homeY-e.y,e.homeX-e.x);moveEntity(e,Math.cos(a)*e.speed*.7*dt,Math.sin(a)*e.speed*.7*dt)}if(e.leashTime>=BALANCE.progression.guardianLeashSeconds&&(e.hp<e.maxHp||e.guardianWave>0))resetEliteEnemy(e,'leash');return}e.leashTime=0;e.aggro=true;const ph=guardianPhaseFor(e);if(ph!==e.guardianPhase){e.guardianPhase=ph;e.attackCD=.8;e.guardianPattern=0;if(e.guardian==='moss'){e.guard=Math.max(e.guard,1.45);e.guardAngle=angle(e,player);e.vulnerable=Math.max(e.vulnerable,.18);text(e.x,e.y-e.r-42,'ESPINHOS RENASCEM','#dce5b6',11)}else e.vulnerable=Math.max(e.vulnerable,.45);guardianSpeak(e,ph===2?'Ainda não terminou.':'Agora acabou a delicadeza.','danger');burst(e.x,e.y,e.color||'#e2cd91',28,170);sound('boss')}
